#include <omp.h>
#include <cstddef>
#include <vector>

using std::size_t;

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Guard against invalid/incomplete input and size_t overflow in N*N.
    if (A.size() / N < N) {
        return 0;
    }

    int max_degree = 0;

    #pragma omp parallel for reduction(max:max_degree) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        int degree = 0;
        const size_t row_offset = static_cast<size_t>(i) * N;

        for (size_t j = 0; j < N; ++j) {
            degree += A[row_offset + j];
        }

        if (degree > max_degree) {
            max_degree = degree;
        }
    }

    return max_degree;
}
